import AppKit
import WebKit

final class Check: NSObject, WKNavigationDelegate {
    let web: WKWebView
    let width: CGFloat
    init(width: CGFloat) {
        self.width = width
        self.web = WKWebView(frame: NSRect(x: 0, y: 0, width: width, height: width == 375 ? 1800 : 1024))
        super.init()
        web.navigationDelegate = self
    }
    func start() {
        let url = URL(fileURLWithPath: FileManager.default.currentDirectoryPath).appendingPathComponent(\"index.html\")
        web.loadFileURL(url, allowingReadAccessTo: url.deletingLastPathComponent())
    }
    func webView(_ webView: WKWebView, didFinish navigation: WKNavigation"'!) {
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
            let script = """
            JSON.stringify({viewport:innerWidth,width:document.documentElement.scrollWidth,metrics:document.querySelector('"'.metrics').getBoundingClientRect().toJSON(),chart:document.querySelector('.activity').getBoundingClientRect().toJSON(),table:document.querySelector('.bookings').getBoundingClientRect().toJSON(),promo:document.querySelector('.promo').getBoundingClientRect().toJSON()})
            \"\"\"
            webView.evaluateJavaScript(script) { result, error in
                print(result ?? error?.localizedDescription ?? \"No geometry\")
                self.testInteractions()
            }
        }
    }
    func testInteractions() {
        let script = \"\"\"
        (()=>{const errors=[];const check=(v,m)=>{if("'!v)errors.push(m)};document.querySelector('"'[data-period=\"month\"]').click();check(document.querySelector('[data-period=\"month\"]').getAttribute('aria-pressed')==='true','Month active');check(document.querySelector('#chart-days text').textContent==='Oct 1','Month labels');document.querySelector('[data-period=\"week\"]').click();document.querySelector('[data-page=\"Members\"]').click();check(document.querySelector('#current-page').textContent==='Members','Navigation');document.querySelector('[data-page=\"Overview\"]').click();document.querySelector('#new-booking').click();check(document.querySelector('#booking-dialog').open,'Open booking');document.querySelector('#booking-dialog [data-close]').click();check("'!document.querySelector('"'#booking-dialog').open,'Close booking');return JSON.stringify({interactionErrors:errors})})()
        \"\"\"
        web.evaluateJavaScript(script) { result, error in
            print(result ?? error?.localizedDescription ?? \"No interactions\")
            let config = WKSnapshotConfiguration()
            self.web.takeSnapshot(with: config) { picture, error in
                if let picture = picture, let tiff = picture.tiffRepresentation, let bitmap = NSBitmapImageRep(data: tiff), let png = bitmap.representation(using: .png, properties: [:]) {
                    try? png.write(to: URL(fileURLWithPath: FileManager.default.currentDirectoryPath).appendingPathComponent(self.width == 375 ? \"mobile-check.png\" : \"desktop-check.png\"))
                    print(\"Snapshot saved\")
                } else {print(error?.localizedDescription ?? \"Snapshot failed\")}
                NSApplication.shared.terminate(nil)
            }
        }
    }
}
let app = NSApplication.shared
app.setActivationPolicy(.prohibited)
let check = Check(width: CommandLine.arguments.contains(\"mobile\") ? 375 : 1536)
check.start()
app.run()
EOF
